Use `BackgroundTasks.enqueue_job` with a job ID and return the task's UUID. The client polls `/jobs/{job_id}` until it returns `{"status": "done"}`.

```python
import uuid

from fastapi import BackgroundTasks, FastAPI, HTTPException
from pydantic import BaseModel

app = FastAPI()
JOBS = {}

class Job(BaseModel):
    id: str
    status: str

@app.post("/jobs", response_model=Job)
async def create_job(background_tasks: BackgroundTasks):
    job_id = str(uuid.uuid4())
    background_tasks.enqueue_job("slow_task", job_id=job_id)
    JOBS[job_id] = {"status": "pending"}
    return {"id": job_id, "status": "pending"}

@app.get("/jobs/{job_id}")
async def get_job(job_id: str):
    job = JOBS.get(job_id)
    if job is None:
        raise HTTPException(status_code=404, detail="Job not found")
    return job

@app.background.task
def slow_task(job_id: str):
    import time
    time.sleep(10)
    JOBS[job_id]["status"] = "done"
```

